10	// retrievalTimeout bounds a single address fetch, including the body read.
11	const retrievalTimeout = 30 * time.Second
12	
13	// retrievalResponse is the JSON body of POST /v1/retrievals/{cid}. It
14	// extends the upload response with the provider and address that supplied
15	// the body; both are null when the object was already stored locally.
16	type retrievalResponse struct {
17		CID        string   `json:"cid"`
18		Size       int      `json:"size"`
19		ChunkSize  int      `json:"chunkSize"`
20		Chunks     []string `json:"chunks"`
21		Created    bool     `json:"created"`
22		ProviderID *string  `json:"providerId"`
23		Address    *string  `json:"address"`
24	}
25	
26	// retriever fetches missing objects from the addresses published in the
27	// provider directory.
28	type retriever struct {
29		objects   *store
30		providers *providerDirectory
31		client    *http.Client
32	}
33	
34	func newRetriever(objects *store, providers *providerDirectory) *retriever {
35		return &retriever{
36			objects:   objects,
37			providers: providers,
38			client: &http.Client{
39				Timeout: retrievalTimeout,
40				// Redirects are not followed: a 3xx response fails the address.
41				CheckRedirect: func(_ *http.Request, _ []*http.Request) error {
42					return http.ErrUseLastResponse
43				},
44			},
45		}
46	}
47	
48	// postRetrieval handles POST /v1/retrievals/{cid}.
49	func (rv *retriever) postRetrieval(w http.ResponseWriter, r *http.Request) {
50		if r.Method != http.MethodPost {
51			w.Header().Set("Allow", http.MethodPost)
52			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
53			return
54		}
