265		codes := make([]int, n)
266		created := make([]bool, n)
267		cids := make([]string, n)
268		for i := 0; i < n; i++ {
269			wg.Add(1)
270			go func(i int) {
271				defer wg.Done()
272				rec := postBody(t, h, payload, "application/octet-stream")
273				resp := decodeObjectResponse(t, rec)
274				codes[i], created[i], cids[i] = rec.Code, resp.Created, resp.CID
275			}(i)
276		}
277		wg.Wait()
278	
279		trues := 0
280		for i := 0; i < n; i++ {
281			if created[i] {
282				trues++
283				if codes[i] != http.StatusCreated {
284					t.Fatalf("created upload returned status %d, want %d", codes[i], http.StatusCreated)
285				}
286			} else if codes[i] != http.StatusOK {
287				t.Fatalf("duplicate upload returned status %d, want %d", codes[i], http.StatusOK)
288			}
289			if cids[i] != cids[0] {
290				t.Fatal("concurrent uploads returned different cids")
291			}
292		}
293		if trues != 1 {
